-- ============================================================================
-- demo_data.sql - jeu d'experiences d'usinage synthetiques
--
-- 360 experiences generees par scripts/generate_demo_experiments.py
-- Les mesures respectent des modèles simplifiés inspirés de la coupe (Kienzle, Taylor,
-- rugosite theorique) : l'ACP et la recommandation par similarite produisent
-- donc des resultats interpretables, contrairement a du bruit aleatoire.
--
-- Aucune mesure reelle du partenariat de recherche n'est redistribuee ici.
--
-- Usage :
--   mysql -u root -p < db/schema.sql
--   mysql -u root -p cutting < db/demo_data.sql
-- ============================================================================

